using System.Collections.ObjectModel;using OdinVault.Manager.Wpf.Infrastructure;using OdinVault.Manager.Wpf.Services;namespace OdinVault.Manager.Wpf.ViewModels;internal sealed class ReportsViewModel:ObservableObject{readonly AgentDashboardClient c;bool loading;string? error;string total="—",success="—",failed="—",rate="—";public ObservableCollection<ReportDatabaseRow> Databases{get;}=[];public bool IsLoading{get=>loading;private set=>Set(ref loading,value);}public string? Error{get=>error;private set=>Set(ref error,value);}public string Total{get=>total;private set=>Set(ref total,value);}public string Success{get=>success;private set=>Set(ref success,value);}public string Failed{get=>failed;private set=>Set(ref failed,value);}public string Rate{get=>rate;private set=>Set(ref rate,value);}public ReportsViewModel(AgentDashboardClient c)=>this.c=c;public async Task LoadAsync(){IsLoading=true;Error=null;try{var x=await c.ReportAsync();if(x is null)return;Total=x.Summary.TotalBackups.ToString("N0");Success=x.Summary.Succeeded.ToString("N0");Failed=x.Summary.Failed.ToString("N0");Rate=x.Summary.SuccessRate is null?"—":$"{x.Summary.SuccessRate:0.#}%";Databases.Clear();foreach(var d in x.Databases)Databases.Add(new(d.DatabaseName,d.TotalBackups,d.Succeeded,d.Failed,d.VerifyFailed,d.ReplicaFailed,d.SuccessRate is null?"—":$"{d.SuccessRate:0.#}%",d.Severity));}catch(Exception e){Error=e.Message;}finally{IsLoading=false;}}}internal sealed record ReportDatabaseRow(string Database,int Total,int Success,int Failed,int VerifyFailed,int ReplicaFailed,string Rate,string Severity);